237	def tag_filter(secs):
238	    """Tag chips that filter the grid. Buttons carry aria-pressed so the state is
239	    exposed to assistive tech, and the result count is announced live."""
240	    tags = load_tags()
241	    if not tags:
242	        return ""
243	    import collections
244	    counts = collections.Counter(t for fn, ts in tags.items() for t in ts)
245	    top = [t for t, _ in counts.most_common(28)]
246	    h = ['<section id="top"><h2 style="margin-top:40px">Browse by concept</h2>',
247	         '<p class="sub">Every image carries three concept tags. Pick one to filter the whole library.</p>',
248	         '<div class="tagbar">']
249	    h.append('<button type="button" data-tag="" aria-pressed="true">All</button>')
250	    for t in sorted(top):
251	        h.append(f'<button type="button" data-tag="{t}" aria-pressed="false">{t}'
252	                 f' <span style="opacity:.55">{counts[t]}</span></button>')
253	    h.append('</div><p class="sr" role="status" aria-live="polite" id="filter-status"></p></section>')
254	    return "\n".join(h)
